1	use std::io::Read;
2	use std::path::Path;
3	use std::process::Stdio;
4	use std::time::{Duration, Instant};
5	
6	use callisto_model::{known_credential_env_values, redact_known_secrets, CommandError, CommandOutput, CommandRunner};
7	
8	/// Caps how much of a subprocess's stdout/stderr this process will retain
9	/// in memory. The pipe is still drained in full past this point (bytes
10	/// beyond the cap are read and discarded, never accumulated) so a chatty
11	/// child can never deadlock waiting on a full OS pipe buffer -- this
12	/// bounds memory, not duration (`PUBLISH_TIMEOUT_SECS` bounds that
13	/// separately).
14	const MAX_CAPTURED_OUTPUT_BYTES: usize = 10 * 1024 * 1024;
15	
16	pub struct CliCommandRunner;
17	
18	impl CommandRunner for CliCommandRunner {
19	    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
20	        let output = std::process::Command::new(program)
21	            .args(args)
22	            .current_dir(cwd)
23	            .stdin(Stdio::null())
24	            .stdout(Stdio::piped())
25	            .stderr(Stdio::piped())
26	            .output();
27	
28	        match output {
29	            Ok(o) => {
30	                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
31	                // Keep raw stderr available to callers for protocol/error
32	                // classification, but never leak credentials to the terminal.
33	                if !stderr.is_empty() {
34	                    let secrets = known_credential_env_values(std::env::vars());
35	                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
36	                }
37	                Ok(CommandOutput {
38	                    exit_code: o.status.code(),
39	                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
40	                    stderr,
41	                })
42	            }
43	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(CommandError::NotFound {
44	                program: program.to_string(),
45	            }),
46	            Err(e) => Err(CommandError::Io {
47	                program: program.to_string(),
48	                message: e.to_string(),
49	            }),
50	        }
51	    }
52	
53	    fn run_with_timeout(
54	        &self,
55	        program: &str,
56	        args: &[&str],
57	        cwd: &Path,
58	        timeout: Duration,
59	    ) -> Result<CommandOutput, CommandError> {
60	        // `known_credential_env_values` is scanned here, at the trait-method
61	        // call site, rather than inside `run_with_timeout_impl` itself: this
62	        // keeps the impl fn pure and directly unit-testable with a synthetic
63	        // secrets list (no process-env mutation, which would race against
64	        // other tests running in parallel in this binary).
65	        run_with_timeout_impl(
66	            program,
67	            args,
68	            cwd,
69	            timeout,
70	            StderrMode::Live,
71	            known_credential_env_values(std::env::vars()),
72	        )
73	    }
74	
75	    fn run_quiet(
76	        &self,
77	        program: &str,
78	        args: &[&str],
79	        cwd: &Path,
80	        timeout: Duration,
81	    ) -> Result<CommandOutput, CommandError> {
82	        // Quiet mode never echoes stderr live (see `StderrMode::Quiet`
83	        // below), so there's nothing to redact -- pass an empty secrets
84	        // list rather than paying for an env scan that can only go unused.
85	        run_with_timeout_impl(program, args, cwd, timeout, StderrMode::Quiet, Vec::new())
86	    }
87	}
88	
89	/// Controls whether [`run_with_timeout_impl`]'s stderr reader thread prints
90	/// each line live as it arrives. Captured `CommandOutput.stderr` is
91	/// identical either way -- this only affects what's echoed to the
92	/// terminal while the subprocess runs.
93	#[derive(Clone, Copy, PartialEq, Eq)]
94	enum StderrMode {
95	    Live,
96	    Quiet,
97	}
98	
99	/// `live_secrets`: known-credential values (see
100	/// [`callisto_model::known_credential_env_values`]) to redact from each
101	/// line *before* it's echoed live to the terminal via `eprintln!`. This is
102	/// deliberately separate from -- and does not affect -- the `captured`
103	/// buffer that becomes the returned `CommandOutput.stderr`: that copy must
104	/// stay byte-for-byte raw so downstream classifiers (e.g.
105	/// `extract_retry_after_duration`, `detect_auth_failure`) can still match
106	/// exact upstream text. Callers pass the secrets list in rather than this
107	/// function reading the environment itself, keeping it pure and testable
108	/// with a synthetic list.
109	fn run_with_timeout_impl(
110	    program: &str,
111	    args: &[&str],
112	    cwd: &Path,
113	    timeout: Duration,
114	    stderr_mode: StderrMode,
115	    live_secrets: Vec<String>,
116	) -> Result<CommandOutput, CommandError> {
117	    let mut child = std::process::Command::new(program)
118	        .args(args)
119	        .current_dir(cwd)
120	        .stdin(Stdio::null())
121	        .stdout(Stdio::piped())
122	        .stderr(Stdio::piped())
123	        .spawn()
124	        .map_err(|e| {
125	            if e.kind() == std::io::ErrorKind::NotFound {
126	                CommandError::NotFound {
127	                    program: program.to_string(),
128	                }
129	            } else {
130	                CommandError::Io {
131	                    program: program.to_string(),
132	                    message: e.to_string(),
133	                }
134	            }
135	        })?;
136	
137	    // Read stdout/stderr in separate threads to prevent pipe-buffer deadlock
138	    // when the child produces output while we wait for it to exit.
139	    let stdout_handle = child.stdout.take().unwrap();
140	    let stderr_handle = child.stderr.take().unwrap();
141	
142	    // The reader threads signal completion over a channel rather than
143	    // being joined directly. Killing (or the natural exit of) the
144	    // direct child does NOT close pipe fds held open by a descendant
145	    // process that inherited them (common for npm/cargo/python publish
146	    // lifecycle scripts spawning subprocesses). If that happens, the
147	    // blocking `read()` inside these threads never returns. Using
148	    // `recv_timeout` below lets us bound how long we wait for them
149	    // without ever blocking the caller indefinitely.
150	    let (stdout_tx, stdout_rx) = std::sync::mpsc::channel::<String>();
151	    let (stderr_tx, stderr_rx) = std::sync::mpsc::channel::<String>();
152	
153	    std::thread::spawn(move || {
154	        let mut reader = stdout_handle;
155	        let mut captured: Vec<u8> = Vec::new();
156	        let mut truncated = false;
157	        let mut chunk = [0u8; 65536];
158	        loop {
159	            match reader.read(&mut chunk) {
160	                Ok(0) => break,
161	                Ok(n) => {
162	                    // Bytes past the cap are still read (draining the
163	                    // pipe so the child never blocks on a full buffer)
164	                    // but not retained.
165	                    if !truncated {
166	                        let remaining = MAX_CAPTURED_OUTPUT_BYTES - captured.len();
167	                        let take = n.min(remaining);
168	                        captured.extend_from_slice(&chunk[..take]);
169	                        if take < n {
170	                            truncated = true;
171	                        }
172	                    }
173	                }
174	                Err(_) => break,
175	            }
176	        }
177	        let mut text = String::from_utf8_lossy(&captured).into_owned();
178	        if truncated {
179	            text.push_str("\n...[output truncated]\n");
180	        }
181	        drop(stdout_tx.send(text));
182	    });
183	    // Stream stderr line-by-line so publish progress (cargo/npm/twine
184	    // write to stderr) appears in real time rather than after the
185	    // process exits, while capping the accumulated text returned to
186	    // the caller. Deliberately reads raw bytes rather than using
187	    // `BufReader::lines()`: that iterator has no size bound on a
188	    // single line, so a flood with no newlines at all would still
189	    // buffer unboundedly inside it before ever yielding a line to cap.
190	    // `stderr_mode` gates only the live eprintln -- captured output is
191	    // identical either way (Live vs. Quiet).
192	    //
193	    // NOTE: captured output is no longer necessarily byte-identical to
194	    // what was printed live. Each line handed to `eprintln!` is redacted
195	    // via `live_secrets` first (registry CLIs can echo a credential
196	    // verbatim in their own stderr diagnostics), while `captured` -- and
197	    // therefore the returned `CommandOutput.stderr` -- deliberately stays
198	    // raw so error classifiers keep matching exact upstream text. For a
199	    // credential-bearing line, the terminal sees `[REDACTED]`; the
200	    // returned `CommandOutput.stderr` still has the real value.
201	    std::thread::spawn(move || {
202	        let mut reader = stderr_handle;
203	        let mut captured: Vec<u8> = Vec::new();
204	        let mut truncated = false;
205	        let mut pending_line: Vec<u8> = Vec::new();
206	        let mut chunk = [0u8; 65536];
207	        loop {
208	            match reader.read(&mut chunk) {
209	                Ok(0) => break,
210	                Ok(n) => {
211	                    let data = &chunk[..n];
212	                    for &b in data {
213	                        if b == b'\n' {
214	                            if pending_line.last() == Some(&b'\r') {
215	                                pending_line.pop();
216	                            }
217	                            if stderr_mode == StderrMode::Live {
218	                                let line = redact_known_secrets(&String::from_utf8_lossy(&pending_line), &live_secrets);
219	                                eprintln!("{line}");
220	                            }
221	                            pending_line.clear();
222	                        } else if pending_line.len() < MAX_CAPTURED_OUTPUT_BYTES {
223	                            pending_line.push(b);
224	                        }
225	                    }
226	                    if !truncated {
227	                        let remaining = MAX_CAPTURED_OUTPUT_BYTES - captured.len();
228	                        let take = data.len().min(remaining);
229	                        captured.extend_from_slice(&data[..take]);
230	                        if take < data.len() {
231	                            truncated = true;
232	                        }
233	                    }
234	                }
235	                Err(_) => break,
236	            }
237	        }
238	        if !pending_line.is_empty() {
239	            if pending_line.last() == Some(&b'\r') {
240	                pending_line.pop();
241	            }
242	            if stderr_mode == StderrMode::Live {
243	                let line = redact_known_secrets(&String::from_utf8_lossy(&pending_line), &live_secrets);
244	                eprintln!("{line}");
245	            }
246	        }
247	        let mut text = String::from_utf8_lossy(&captured).into_owned();
248	        if truncated {
249	            text.push_str("\n...[output truncated]\n");
250	        }
251	        drop(stderr_tx.send(text));
252	    });
253	
254	    // Grace period to wait for the reader threads after the direct
255	    // child has exited (or been killed). Bounded so a lingering
256	    // descendant holding the pipe open can never hang the caller.
257	    const READER_GRACE: Duration = Duration::from_secs(3);
258	
259	    let deadline = Instant::now() + timeout;
260	    let status = loop {
261	        match child.try_wait().map_err(|e| CommandError::Io {
262	            program: program.to_string(),
263	            message: e.to_string(),
264	        })? {
265	            Some(s) => break s,
266	            None => {
267	                if Instant::now() >= deadline {
268	                    drop(child.kill());
269	                    drop(child.wait());
270	                    // Reader threads are intentionally not joined here:
271	                    // if a descendant process is still holding a pipe
272	                    // fd open, join() could block forever. We wait a
273	                    // bounded grace period for output, then abandon the
274	                    // threads (they leak until the descendant
275	                    // eventually exits and closes the fd -- a thread
276	                    // leak, not a memory-safety issue).
277	                    let stdout = stdout_rx.recv_timeout(READER_GRACE).ok();
278	                    let stderr = stderr_rx.recv_timeout(READER_GRACE).ok();
279	                    if stdout.is_none() || stderr.is_none() {
280	                        eprintln!(
281	                            "warning: `{program}` timed out and a descendant process \
282	                                 appears to still hold its output pipes open; captured \
283	                                 output may be incomplete"
284	                        );
285	                    }
286	                    return Err(CommandError::TimedOut {
287	                        program: program.to_string(),
288	                        seconds: timeout.as_secs(),
289	                    });
290	                }
291	                std::thread::sleep(Duration::from_millis(50));
292	            }
293	        }
294	    };
295	
296	    // The direct child has exited on its own. Even so, a descendant
297	    // process can still hold the pipe fds open (e.g. a backgrounded
298	    // job spawned by a shell script), so bound the wait here too.
299	    let stdout_result = stdout_rx.recv_timeout(READER_GRACE);
300	    let stderr_result = stderr_rx.recv_timeout(READER_GRACE);
301	    if stdout_result.is_err() || stderr_result.is_err() {
302	        eprintln!(
303	            "warning: `{program}` exited but a descendant process appears to still \
304	                 hold its output pipes open; captured output may be incomplete"
305	        );
306	    }
307	
308	    Ok(CommandOutput {
309	        exit_code: status.code(),
310	        stdout: stdout_result.unwrap_or_default(),
311	        stderr: stderr_result.unwrap_or_default(),
312	    })
313	}
314	
315	#[cfg(test)]
316	mod tests {
317	    use super::*;
318	
319	    #[test]
320	    fn run_with_timeout_kills_slow_process_and_returns_timed_out() {
321	        let runner = CliCommandRunner;
322	        // sleep for 1 second with a 100ms timeout — process must be killed.
323	        let err = runner
324	            .run_with_timeout("sleep", &["1"], std::path::Path::new("."), Duration::from_millis(100))
325	            .unwrap_err();
326	        assert!(
327	            matches!(err, CommandError::TimedOut { .. }),
328	            "expected TimedOut, got: {err:?}"
329	        );
330	    }
331	
332	    #[test]
333	    fn run_with_timeout_returns_output_for_fast_process() {
334	        let runner = CliCommandRunner;
335	        let out = runner
336	            .run_with_timeout("true", &[], std::path::Path::new("."), Duration::from_secs(5))
337	            .unwrap();
338	        assert!(out.success());
339	    }
340	
341	    /// Regression test for a hung-descendant deadlock: killing the direct
342	    /// child does not close pipe fds inherited by a grandchild process that
343	    /// outlives it. The direct child (`sh`) exits almost immediately, but a
344	    /// backgrounded grandchild (`sleep 30`) keeps stderr open well past
345	    /// that. If the reader threads are joined unconditionally, this call
346	    /// hangs for ~30s regardless of the requested timeout. The fix bounds
347	    /// how long we wait on the reader threads so the call always returns
348	    /// promptly.
349	    #[test]
350	    fn run_with_timeout_bounds_reader_join_when_descendant_holds_pipe_open() {
351	        let runner = CliCommandRunner;
352	        let start = Instant::now();
353	        let result = runner.run_with_timeout(
354	            "sh",
355	            &["-c", "sleep 30 >&2 & exit 0"],
356	            std::path::Path::new("."),
357	            Duration::from_secs(2),
358	        );
359	        let elapsed = start.elapsed();
360	        assert!(
361	            elapsed < Duration::from_secs(6),
362	            "run_with_timeout must not block on a descendant process holding \
363	             stdio pipes open; took {elapsed:?}, result: {result:?}"
364	        );
365	        assert!(
366	            result.is_ok(),
367	            "expected Ok despite a lingering descendant holding the pipe open, got: {result:?}"
368	        );
369	    }
370	
371	    /// F-007: subprocess stderr must be streamed line-by-line rather than
372	    /// buffered until process exit. The fix: switch from `read_to_string`
373	    /// (accumulates everything) to a `BufReader::lines` loop that emits each
374	    /// line to the terminal immediately while still accumulating the full
375	    /// text for caller analysis.
376	    ///
377	    /// We verify that `CommandOutput::stderr` still contains the full stderr
378	    /// text after streaming (so callers can still classify errors from it).
379	    #[test]
380	    fn run_with_timeout_stderr_is_fully_captured_after_streaming() {
381	        let runner = CliCommandRunner;
382	        // A process that prints multiple lines to stderr, one at a time.
383	        // Using sh -c with printf to emit to stderr.
384	        let out = runner
385	            .run_with_timeout(
386	                "sh",
387	                &["-c", "echo line1 >&2; echo line2 >&2"],
388	                std::path::Path::new("."),
389	                Duration::from_secs(5),
390	            )
391	            .unwrap();
392	
393	        assert!(out.success());
394	        assert!(
395	            out.stderr.contains("line1") && out.stderr.contains("line2"),
396	            "stderr must contain all emitted lines even when streamed; got: {:?}",
397	            out.stderr
398	        );
399	    }
400	
401	    /// Regression test for the timeout-KILL branch's grace-period logic
402	    /// (runner.rs:124-146), structurally similar to but independently
403	    /// written from the normal-exit branch's (runner.rs:153-163, covered
404	    /// by `run_with_timeout_bounds_reader_join_when_descendant_holds_pipe_open`).
405	    /// That test's child (`sh`) exits almost immediately, only exercising
406	    /// the exit branch. Here the child (`sh -c "sleep 30 >&2 & sleep 10"`)
407	    /// outlives the timeout, so `run_with_timeout` must actually kill it,
408	    /// while a backgrounded grandchild (`sleep 30 >&2`) keeps stderr open
409	    /// independently of the kill.
410	    ///
411	    /// The warning is emitted via `eprintln!` inside `run_with_timeout`
412	    /// (not captured in `CommandOutput`), so this test re-execs the binary
413	    /// as a child with `--nocapture` to capture real OS-level stderr
414	    /// instead of having it swallowed by the outer harness.
415	    #[test]
416	    fn run_with_timeout_warns_on_timeout_branch_when_descendant_holds_pipe_open() {
417	        const CHILD_ENV: &str = "CALLISTO_RUN_TIMEOUT_KILL_CHILD";
418	
419	        if std::env::var(CHILD_ENV).is_ok() {
420	            let runner = CliCommandRunner;
421	            // `sh` on this platform forks a separate process for the
422	            // foreground `sleep 10` rather than exec-replacing itself (it
423	            // must remain able to reap the backgrounded job), so killing
424	            // the direct child does not kill either descendant. Both the
425	            // backgrounded `sleep 30` and the foreground `sleep 10` inherit
426	            // the piped stdout/stderr fds unless redirected away, so each
427	            // is redirected explicitly: `sleep 30`'s stdout goes to
428	            // /dev/null so only its stderr lingers (the condition under
429	            // test), and `sleep 10`'s stdout/stderr both go to /dev/null so
430	            // it doesn't *also* hold either pipe open, which would stack a
431	            // second sequential 3s grace wait on top of the first.
432	            drop(runner.run_with_timeout(
433	                "sh",
434	                &["-c", "sleep 30 >&2 1>/dev/null & sleep 10 >/dev/null 2>&1"],
435	                std::path::Path::new("."),
436	                Duration::from_millis(800),
437	            ));
438	            return;
439	        }
440	
441	        let exe = std::env::current_exe().expect("current_exe should be available in tests");
442	        let start = Instant::now();
443	        let output = std::process::Command::new(exe)
444	            .arg("--exact")
445	            .arg("runner::tests::run_with_timeout_warns_on_timeout_branch_when_descendant_holds_pipe_open")
446	            .arg("--nocapture")
447	            .env(CHILD_ENV, "1")
448	            .output()
449	            .expect("failed to re-exec test binary");
450	        let elapsed = start.elapsed();
451	
452	        assert!(
453	            elapsed < Duration::from_secs(6),
454	            "run_with_timeout's timeout-kill branch must not block past its \
455	             bounded grace period even when a descendant holds stdio pipes \
456	             open; took {elapsed:?}"
457	        );
458	
459	        let stderr = String::from_utf8_lossy(&output.stderr);
460	        assert!(
461	            stderr.contains("timed out and a descendant process appears to still hold its output pipes open"),
462	            "expected the timeout branch's specific warning text in child stderr, got: {stderr}"
463	        );
464	    }
465	
466	    /// A subprocess that writes far more than `MAX_CAPTURED_OUTPUT_BYTES`
467	    /// to stdout must not have all of it retained in `CommandOutput` (an
468	    /// unbounded accumulation is a memory-exhaustion DoS before the
469	    /// wall-clock publish timeout ever fires), but the pipe must still be
470	    /// drained in full -- proven here by the call completing well within
471	    /// its timeout instead of hanging (a reader that stops calling
472	    /// `read()` after the cap would leave the child blocked writing to a
473	    /// full OS pipe buffer).
474	    #[test]
475	    fn run_with_timeout_caps_accumulated_stdout_and_still_drains_the_pipe() {
476	        let runner = CliCommandRunner;
477	        let over_cap = MAX_CAPTURED_OUTPUT_BYTES + 1_000_000;
478	        let start = Instant::now();
479	        let out = runner
480	            .run_with_timeout(
481	                "sh",
482	                &["-c", &format!("head -c {over_cap} /dev/zero")],
483	                std::path::Path::new("."),
484	                Duration::from_secs(30),
485	            )
486	            .unwrap();
487	        let elapsed = start.elapsed();
488	
489	        assert!(out.success());
490	        assert!(
491	            elapsed < Duration::from_secs(15),
492	            "must not hang waiting for the child to finish writing past the cap; took {elapsed:?}"
493	        );
494	        assert!(
495	            out.stdout.len() < over_cap,
496	            "captured stdout must be bounded, not the full {over_cap} bytes written; got {} bytes",
497	            out.stdout.len()
498	        );
499	        assert!(
500	            out.stdout.contains("[output truncated]"),
501	            "truncated output must say so"
502	        );
503	    }
504	
505	    /// Same as the stdout case, but for stderr -- and deliberately with NO
506	    /// newlines at all, so the flood can't be capped by a per-line
507	    /// mechanism (a `BufReader::lines()`-based reader has no size bound on
508	    /// a single line and would buffer the entire flood internally before
509	    /// ever handing a line back, defeating any cap applied only after a
510	    /// line is yielded).
511	    #[test]
512	    fn run_with_timeout_caps_accumulated_stderr_with_no_newlines_and_still_drains_the_pipe() {
513	        let runner = CliCommandRunner;
514	        let over_cap = MAX_CAPTURED_OUTPUT_BYTES + 1_000_000;
515	        let start = Instant::now();
516	        let out = runner
517	            .run_with_timeout(
518	                "sh",
519	                &["-c", &format!("head -c {over_cap} /dev/zero >&2")],
520	                std::path::Path::new("."),
521	                Duration::from_secs(30),
522	            )
523	            .unwrap();
524	        let elapsed = start.elapsed();
525	
526	        assert!(out.success());
527	        assert!(
528	            elapsed < Duration::from_secs(15),
529	            "must not hang waiting for the child to finish writing past the cap; took {elapsed:?}"
530	        );
531	        assert!(
532	            out.stderr.len() < over_cap,
533	            "captured stderr must be bounded, not the full {over_cap} bytes written; got {} bytes",
534	            out.stderr.len()
535	        );
536	        assert!(
537	            out.stderr.contains("[output truncated]"),
538	            "truncated output must say so"
539	        );
540	    }
541	
542	    /// Output comfortably under the cap must be completely unaffected --
543	    /// no truncation marker, byte-for-byte length preserved.
544	    #[test]
545	    fn run_with_timeout_does_not_truncate_output_under_the_cap() {
546	        let runner = CliCommandRunner;
