    /// Guards against over-redaction breaking downstream error classification:
    /// even when a known-credential env var is present and appears in the
    /// child's stderr alongside a rate-limit/auth marker, the *captured*
    /// `CommandOutput.stderr` returned to the caller must remain raw so
    /// `extract_retry_after_duration`/`detect_auth_failure`-style matching
    /// against exact upstream text keeps working. Re-execs so the child
    /// actually has `NPM_TOKEN` set when it calls `run_with_timeout`.
    #[test]
    fn run_with_timeout_still_captures_unredacted_stderr_for_classification_even_with_known_secret_present() {
        const CHILD_ENV: &str = "CALLISTO_RUN_TIMEOUT_CAPTURE_CHILD";
        const TOKEN: &str = "tok-abcd-9999";

        if std::env::var(CHILD_ENV).is_ok() {
            let runner = CliCommandRunner;
            let out = runner
                .run_with_timeout(
                    "sh",
                    &["-c", &format!("echo '429 too many requests, token={TOKEN}' >&2")],
                    std::path::Path::new("."),
                    Duration::from_secs(5),
                )
                .expect("run_with_timeout must succeed");
            assert!(
                out.stderr.contains(TOKEN),
                "captured CommandOutput.stderr must retain the raw token for classifiers \
                 like extract_retry_after_duration/detect_auth_failure, got: {:?}",
                out.stderr
            );
            assert!(
                out.stderr.contains("429"),
                "captured stderr must retain the rate-limit marker text, got: {:?}",
                out.stderr
            );
            println!("CHILD_REACHED_AND_VERIFIED_CAPTURE");
            return;
        }

        let exe = std::env::current_exe().expect("current_exe should be available in tests");
        let output = std::process::Command::new(exe)
            .arg("--exact")
            .arg(
                "runner::tests::run_with_timeout_still_captures_unredacted_stderr_for_classification_even_with_known_secret_present",
            )
            .arg("--nocapture")
            .env(CHILD_ENV, "1")
            .env("NPM_TOKEN", TOKEN)
            .output()
            .expect("failed to re-exec test binary");

        assert!(
            output.status.success(),
            "child process must exit successfully, got: {:?}, stderr: {}",
            output.status,
            String::from_utf8_lossy(&output.stderr)
        );
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert!(
            stdout.contains("CHILD_REACHED_AND_VERIFIED_CAPTURE"),
            "child must have actually reached and verified capture, not crashed or no-op'd \
             before it; got stdout: {stdout}"
        );
    }

    /// `run_quiet` never streams live at all (see `run_quiet_does_not_stream_stderr_live`),
    /// which means its call site should be able to skip scanning the
    /// environment for credentials entirely (`Vec::new()` short-circuit,
    /// rather than `known_credential_env_values(std::env::vars())`). This
    /// proves the externally-observable half of that: even with a known
    /// credential env var set, the live echo stays completely absent --
    /// neither the raw value nor a `[REDACTED]` marker appears -- which is
    /// what "simply absent" rather than "present-then-redacted" looks like
    /// from outside the process.
    #[test]
    fn run_quiet_does_not_stream_stderr_live_even_with_known_credential_env_value_present() {
        const CHILD_ENV: &str = "CALLISTO_RUN_QUIET_SECRET_CHILD";
        const TOKEN: &str = "quiet-leak-5678";

        if std::env::var(CHILD_ENV).is_ok() {
            let runner = CliCommandRunner;
            let out = runner
                .run_quiet(
                    "sh",
                    &["-c", &format!("echo {TOKEN} >&2")],
                    std::path::Path::new("."),
                    Duration::from_secs(5),
                )
                .expect("run_quiet must succeed");
            assert!(
                out.stderr.contains(TOKEN),
                "run_quiet must still capture the raw text it doesn't stream live"
            );
            println!("CHILD_REACHED_AND_VERIFIED_CAPTURE");
            return;
        }

        let exe = std::env::current_exe().expect("current_exe should be available in tests");
        let output = std::process::Command::new(exe)
            .arg("--exact")
            .arg("runner::tests::run_quiet_does_not_stream_stderr_live_even_with_known_credential_env_value_present")
            .arg("--nocapture")
            .env(CHILD_ENV, "1")
            .env("NPM_TOKEN", TOKEN)
            .output()
            .expect("failed to re-exec test binary");

        assert!(
            output.status.success(),
            "child process must exit successfully, got: {:?}, stderr: {}",
            output.status,
            String::from_utf8_lossy(&output.stderr)
        );
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert!(
            stdout.contains("CHILD_REACHED_AND_VERIFIED_CAPTURE"),
            "child must have actually reached and verified capture; got stdout: {stdout}"
        );

        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            !stderr.contains(TOKEN),
            "run_quiet must not stream the credential live, redacted or not, got: {stderr}"
        );
        assert!(
            !stderr.contains("[REDACTED]"),
            "run_quiet's zero-cost path passes Vec::new() and performs no live echo at all, \
             so no redaction marker should appear either -- proves the short-circuit is \
             actually taken rather than redacting-then-suppressing, got: {stderr}"
        );
    }
}

//! The `pdk`-feature `CommandRunner` impl for [`crate::runner::MoonCommandRunner`].
//! Split into its own file so `--ignore-filename-regex` can exclude it from
//! `cargo llvm-cov` reports: this code calls Extism-host-only `extern "C"`
//! imports (via `warpgate_pdk::exec`) that only resolve when linked against
//! a real wasm32-wasip1 Extism host, so `cargo-llvm-cov` (which instruments
//! a native build) can never observe it executing. It IS black-box tested --
//! via `tests/moon_wasm_sandbox.rs`, which drives the real compiled
//! `callisto-moon.wasm` artifact through an actual wasmtime-backed Extism
//! host -- just not by anything `cargo-llvm-cov`'s native instrumentation
//! can see.

use std::path::Path;

use callisto_model::{CommandError, CommandOutput, CommandRunner};

use crate::runner::{classify_host_failure, MoonCommandRunner};

// Under wasm32-wasip1 (the `pdk` build target), the WASI guest cannot spawn
// child processes at all — `std::process::Command` fails unconditionally.
// moon's PDK bridges process execution back to the host via the
// `exec_command` Extism host function; `warpgate_pdk::exec` is the typed
// wrapper around that host-fn call. A dedicated R&D spike confirmed
// gitoxide's low-level crates cannot read object content under
// wasm32-wasip1 either (memmap2 has no WASI backend), ruling out
// native in-guest git access as an alternative to this host-exec seam;
// see the "gix-in-WASM spike ruled out" finding in the external
// callisto-findings ledger (sibling repo: callisto-findings/FINDINGS.md)
// for the full writeup.
//
// IMPORTANT (bug found and fixed via black-box testing against the real
// wasm sandbox, see `tests/moon_wasm_sandbox.rs`): `warpgate`'s host-side
// `exec_command` implementation (`warpgate::host::exec_command`, in the
// pinned `warpgate` 0.30.5 this crate resolves to transitively) does NOT
// report "command not found" as a normal `ExecCommandOutput`/error value the
// guest's `warpgate_pdk::exec` can catch. Instead, when the requested
// program can't be resolved on `PATH`
// (`system_env::find_command_on_path` returns `None`), the host function's
// own Rust closure returns `Err(WarpgatePluginError::MissingCommand)`
// directly. Extism host functions that return `Err` from their native
// closure abort the *entire* plugin call as a host-function failure — this
// is NOT routed back into the guest as a value `warpgate_pdk::exec`'s
// `Result` can represent; the guest's Rust code (this `run` method
// included) never resumes. From the caller's perspective (moon, or this
// crate's own `PluginContainer::call_func_with` in tests), the whole
// `execute_extension`/`initialize_extension` wire call fails outright
// (`WarpgatePluginError::FailedPluginCall`), not a clean
// `ExecuteExtensionOutput { exit_code: 1, report: { "error": ... } } }`
// response. This directly contradicted this crate's "execute_extension
// never panics/traps; every failure is caught into the report" invariant
// for the single most common real-world failure mode (the host tool the
// extension shells out to -- `moon` itself, or `git` -- being missing).
//
// The fix: proactively check whether `program` exists BEFORE calling
// `warpgate_pdk::exec` at all, via `warpgate_pdk::command_exists` (which
// shells out to `which`/`Get-Command`, not to `program` itself, so a
// missing `program` is reported as a normal `false` rather than tripping
// the same `MissingCommand` trap -- `which`/`Get-Command` being absent is
// an accepted, far less likely residual risk that `warpgate_pdk` itself
// takes on for every consumer). This turns "program not found" into the
// clean `CommandError::NotFound` this method already promises to produce,
// without ever calling `exec` for a program we already know is absent.
#[cfg(feature = "pdk")]
impl CommandRunner for MoonCommandRunner {
    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
        use warpgate_pdk::{get_host_environment, into_virtual_path, ExecCommandInput};

        let host_env = get_host_environment().map_err(|e| classify_host_failure(program, &e.to_string()))?;

        if !warpgate_pdk::command_exists(&host_env, program) {
            return Err(CommandError::NotFound {
                program: program.to_string(),
            });
        }

        let cwd = match into_virtual_path(cwd) {
            Ok(vpath) => Some(vpath),
            Err(e) => return Err(classify_host_failure(program, &e.to_string())),
        };

        let input = ExecCommandInput {
            command: program.to_string(),
            args: args.iter().map(|a| a.to_string()).collect(),
            cwd,
            ..ExecCommandInput::default()
        };

        match warpgate_pdk::exec(input) {
            Ok(output) => Ok(CommandOutput {
                exit_code: Some(output.exit_code),
                stdout: output.stdout,
                stderr: output.stderr,
            }),
            Err(e) => Err(classify_host_failure(program, &e.to_string())),
        }
    }
}

